{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Indacaterol, the closest-scoring analogue with an indole/amine scaffold, has a measured human oral bioavailability of approximately 24%, which is just above the 20% threshold and supports high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A series of indole-containing basic amine drugs, including tropisetron and granisetron, are reported to have oral bioavailability of 50-80% in patients, supporting high oral bioavailability for the query's indole-methylamine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ketanserin, a serotonin antagonist with a basic amine and aromatic heterocycle, has an absolute oral bioavailability of about 50% in healthy subjects, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Bopindolol, an indole-containing drug with a basic amine, has an absolute bioavailability of about 70% in healthy volunteers, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "LY2196044, which contains a carboxamide and basic amine, has an estimated absolute bioavailability of 45% in humans, supporting high bioavailability for the query's amide-amine structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Mebendazole has very low oral bioavailability (about 4.4% in one volunteer), but this is largely due to the poor aqueous solubility of its neutral benzimidazole carbamate, a feature not shared by the query's ionizable methylamine and primary carboxamide; this low-F evidence transfers only weakly.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a tetrahydrocarbazole with a basic methylamine and primary carboxamide, structurally closest to indole/amine drugs with measured human oral bioavailability at or above 20% (indacaterol ~24%, ketanserin ~50%, bopindolol ~70%, LY2196044 45%). The low-F benzimidazole carbamates are poorly soluble neutral compounds and are weak transfer models. Overall, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule is present in the supplied evidence.",
    "All retrieved analogues have low Morgan similarity (<0.25), so transferability is limited.",
    "The threshold is close to the lower end of the expected range; if the true F is near 20%, classification uncertainty increases."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

